static int msm_hdmi_hdcp_scm_wr ( struct hdmi_hdcp_ctrl * hdcp_ctrl , u32 * preg , u32 * pdata , u32 count ) { struct hdmi * hdmi = hdcp_ctrl -> hdmi ; struct qcom_scm_hdcp_req scm_buf [ QCOM_SCM_HDCP_MAX_REQ_CNT ] ; u32 resp , phy_addr , idx = 0 ; int i , ret = 0 ; WARN_ON ( ! pdata || ! preg || ( count == 0 ) ) ; if ( hdcp_ctrl -> tz_hdcp ) { phy_addr = ( u32 ) hdmi -> mmio_phy_addr ; while ( count ) { for ( i = 0 ; i < count && i < QCOM_SCM_HDCP_MAX_REQ_CNT ; i ++ ) { scm_buf [ i ] . addr = phy_addr + preg [ idx ] ; scm_buf [ i ] . val = pdata [ idx ] ; idx ++ ; } ret = qcom_scm_hdcp_req ( scm_buf , i , & resp ) ; if ( ret || resp ) { pr_err ( "%s: error: scm_call ret=%d resp=%u\n" , __func__ , ret , resp ) ; ret = - EINVAL ; break ; } count -= i ; } } else { for ( i = 0 ; i < count ; i ++ ) { hdmi_write ( hdmi , preg [ i ] , pdata [ i ] ) ; } } return ret ; } 